using Nuke.Common;
using Serilog;

partial class Build
{
    [Parameter("Fail on missing TR/TEST coverage (default false)")]
    readonly bool StrictTrAndTestCoverage = false;

    [Parameter("Optional path to workspace SQLite DB for UseCaseFrLinks Realizes coverage (FR-MCP-USECASE-010)")]
    readonly string UseCaseSqlitePath = string.Empty;

    [Parameter("Fail when UseCaseFrLinks Realizes coverage findings are non-empty (default false)")]
    readonly bool StrictUseCaseFrCoverage = false;

    /// <summary>Validate requirements traceability across FR/TR/TEST documents and UseCaseFrLinks.</summary>
    public Target ValidateTraceability => _ => _
        .Executes(() =>
        {
            var docsPath = RootDirectory / "docs" / "Project";
            var functionalLines = File.ReadAllLines(docsPath / "Functional-Requirements.md");
            var technicalLines = File.ReadAllLines(docsPath / "Technical-Requirements.md");
            var testingLines = File.ReadAllLines(docsPath / "Testing-Requirements.md");
            var mappingLines = File.ReadAllLines(docsPath / "TR-per-FR-Mapping.md");
            var matrixLines = File.ReadAllLines(docsPath / "Requirements-Matrix.md");

            // FR-MCP-USECASE-010: load UseCaseFrLinks via shared Realizes algorithm (same wording as UseCaseTraceabilityGate).
            var sqlitePath = string.IsNullOrWhiteSpace(UseCaseSqlitePath)
                ? UseCaseFrTraceabilityLoader.ResolveDefaultSqlitePath(RootDirectory)
                : UseCaseSqlitePath;
            var useCaseFindings = UseCaseFrTraceabilityLoader.LoadFindingsFromSqlite(sqlitePath);
            if (!string.IsNullOrWhiteSpace(sqlitePath))
                Log.Information("UseCaseFrLinks coverage source: {Path} (findings={Count})", sqlitePath, useCaseFindings.Count);
            else
                Log.Information("UseCaseFrLinks coverage source: none (no SQLite path resolved)");

            var result = TraceabilityValidator.Validate(
                functionalLines, technicalLines, testingLines, mappingLines, matrixLines, useCaseFindings);

            if (result.MissingFrInMapping.Count > 0)
            {
                Log.Warning("Missing FR in TR-per-FR-Mapping:");
                result.MissingFrInMapping.ForEach(id => Log.Warning("  - {Id}", id));
            }

            if (result.MissingFrInMatrix.Count > 0)
            {
                Log.Warning("Missing FR in Requirements-Matrix:");
                result.MissingFrInMatrix.ForEach(id => Log.Warning("  - {Id}", id));
            }

            if (result.MissingTrInMatrix.Count > 0)
            {
                Log.Warning("Missing TR in Requirements-Matrix:");
                result.MissingTrInMatrix.ForEach(id => Log.Warning("  - {Id}", id));
            }

            if (result.MissingTestInMatrix.Count > 0)
            {
                Log.Warning("Missing TEST in Requirements-Matrix:");
                result.MissingTestInMatrix.ForEach(id => Log.Warning("  - {Id}", id));
            }

            if (result.UseCaseFrFindings.Count > 0)
            {
                Log.Warning("UseCaseFrLinks Realizes coverage findings:");
                result.UseCaseFrFindings.ForEach(f => Log.Warning("  - {Finding}", f));
            }

            var fail = result.HasFrErrors ||
                       (StrictTrAndTestCoverage && (result.HasTrErrors || result.HasTestErrors)) ||
                       (StrictUseCaseFrCoverage && result.HasUseCaseFrErrors);

            if (fail)
                throw new InvalidOperationException("Traceability validation failed.");

            if (result.HasTrErrors || result.HasTestErrors || result.HasUseCaseFrErrors)
                Log.Information("Traceability validation passed with TR/TEST/UseCaseFr coverage warnings.");
            else
                Log.Information("Traceability validation passed.");
        });
}
using Microsoft.Data.Sqlite;

/// <summary>
/// FR-MCP-USECASE-010: Loads UseCaseFrLinks data for Nuke ValidateTraceability and runs the
/// shared Realizes coverage algorithm via <see cref="TraceabilityValidator.BuildUseCaseFrFindings"/>.
/// Aligns with <c>UseCaseFrCoverageCore</c> / <c>UseCaseTraceabilityGate</c>.
/// </summary>
static class UseCaseFrTraceabilityLoader
{
    /// <summary>
    /// When <paramref name="sqlitePath"/> exists and contains Use Case tables, returns Realizes findings.
    /// When the DB or tables are absent, returns an empty list (docs-only validation remains).
    /// </summary>
    public static IReadOnlyList<string> LoadFindingsFromSqlite(string? sqlitePath)
    {
        if (string.IsNullOrWhiteSpace(sqlitePath) || !File.Exists(sqlitePath))
            return Array.Empty<string>();

        try
        {
            using var conn = new SqliteConnection($"Data Source={sqlitePath}");
            conn.Open();
            if (!TableExists(conn, "UseCases") || !TableExists(conn, "UseCaseFrLinks") || !TableExists(conn, "Requirements"))
                return Array.Empty<string>();

            var useCases = new List<(long UseCaseId, string Title)>();
            using (var cmd = conn.CreateCommand())
            {
                // Soft-delete columns may be present; prefer excluding deleted when IsDeleted exists.
                cmd.CommandText = ColumnExists(conn, "UseCases", "IsDeleted")
                    ? "SELECT UseCaseId, Title FROM UseCases WHERE IFNULL(IsDeleted, 0) = 0"
                    : "SELECT UseCaseId, Title FROM UseCases";
                using var r = cmd.ExecuteReader();
                while (r.Read())
                    useCases.Add((r.GetInt64(0), r.IsDBNull(1) ? string.Empty : r.GetString(1)));
            }

            var frIds = new List<string>();
            using (var cmd = conn.CreateCommand())
            {
                cmd.CommandText = ColumnExists(conn, "Requirements", "IsDeleted")
                    ? "SELECT Id FROM Requirements WHERE Kind = 'fr' AND IFNULL(IsDeleted, 0) = 0"
                    : "SELECT Id FROM Requirements WHERE Kind = 'fr'";
                using var r = cmd.ExecuteReader();
                while (r.Read())
                    frIds.Add(r.GetString(0));
            }

            var links = new List<(long UseCaseId, string FrId)>();
            using (var cmd = conn.CreateCommand())
            {
                cmd.CommandText = ColumnExists(conn, "UseCaseFrLinks", "IsDeleted")
                    ? "SELECT UseCaseId, FrId FROM UseCaseFrLinks WHERE LinkType = 'Realizes' AND IFNULL(IsDeleted, 0) = 0"
                    : "SELECT UseCaseId, FrId FROM UseCaseFrLinks WHERE LinkType = 'Realizes'";
                using var r = cmd.ExecuteReader();
                while (r.Read())
                    links.Add((r.GetInt64(0), r.GetString(1)));
            }

            return TraceabilityValidator.BuildUseCaseFrFindings(useCases, frIds, links);
        }
        catch (Exception)
        {
            // Traceability docs validation must not crash when DB is locked or schema is mid-migration.
            return Array.Empty<string>();
        }
    }

    /// <summary>
    /// Resolves a candidate mcp.db path under the repo for optional UseCaseFrLinks validation.
    /// </summary>
    public static string? ResolveDefaultSqlitePath(string rootDirectory)
    {
        var candidates = new[]
        {
            Path.Combine(rootDirectory, "src", "McpServer.Support.Mcp", "mcp.db"),
            Path.Combine(rootDirectory, "mcp.db"),
        };
        return candidates.FirstOrDefault(File.Exists);
    }

    static bool TableExists(SqliteConnection conn, string name)
    {
        using var cmd = conn.CreateCommand();
        cmd.CommandText = "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=$n";
        cmd.Parameters.AddWithValue("$n", name);
        return Convert.ToInt32(cmd.ExecuteScalar()) > 0;
    }

    static bool ColumnExists(SqliteConnection conn, string table, string column)
    {
        using var cmd = conn.CreateCommand();
        cmd.CommandText = $"PRAGMA table_info({table})";
        using var r = cmd.ExecuteReader();
        while (r.Read())
        {
            if (string.Equals(r.GetString(1), column, StringComparison.OrdinalIgnoreCase))
                return true;
        }
        return false;
    }
}
namespace McpServer.Support.Mcp.UseCases;

/// <summary>
/// FR-MCP-USECASE-006 / FR-MCP-USECASE-010: Pure Realizes coverage algorithm (no DB).
/// Shared by runtime evaluator, traceability gate, and Nuke ValidateTraceability.
/// </summary>
public static class UseCaseFrCoverageCore
{
    /// <summary>Default link type of interest.</summary>
    public const string Realizes = "Realizes";

    /// <summary>
    /// Computes Realizes coverage gaps from in-memory collections.
    /// </summary>
    /// <param name="useCases">Active use cases (id + title).</param>
    /// <param name="frIds">Active functional requirement ids (kind fr).</param>
    /// <param name="realizesLinks">Active Realizes links (useCaseId + frId).</param>
    public static UseCaseFrCoverageSnapshot Compute(
        IReadOnlyList<(long UseCaseId, string Title)> useCases,
        IReadOnlyList<string> frIds,
        IReadOnlyList<(long UseCaseId, string FrId)> realizesLinks)
    {
        ArgumentNullException.ThrowIfNull(useCases);
        ArgumentNullException.ThrowIfNull(frIds);
        ArgumentNullException.ThrowIfNull(realizesLinks);

        var linkedUseCaseIds = realizesLinks.Select(l => l.UseCaseId).ToHashSet();
        var linkedFrIds = realizesLinks.Select(l => l.FrId).ToHashSet(StringComparer.OrdinalIgnoreCase);

        var useCasesWithout = useCases
            .Where(u => !linkedUseCaseIds.Contains(u.UseCaseId))
            .Select(u => new UseCaseFrCoverageItem(u.UseCaseId, u.Title))
            .ToArray();

        var frsWithout = frIds
            .Where(id => !linkedFrIds.Contains(id))
            .OrderBy(id => id, StringComparer.OrdinalIgnoreCase)
            .ToArray();

        return new UseCaseFrCoverageSnapshot(
            TotalUseCases: useCases.Count,
            TotalFunctionalRequirements: frIds.Count,
            LinkedUseCases: linkedUseCaseIds.Count,
            LinkedFunctionalRequirements: linkedFrIds.Count,
            UseCasesWithoutRealizesLink: useCasesWithout,
            FunctionalRequirementsWithoutRealizesUseCase: frsWithout);
    }

    /// <summary>
    /// Formats human-readable Realizes coverage findings (empty when fully covered).
    /// Shared wording for gate and Nuke ValidateTraceability.
    /// </summary>
    public static IReadOnlyList<string> FormatFindings(UseCaseFrCoverageSnapshot snap)
    {
        ArgumentNullException.ThrowIfNull(snap);
        var findings = new List<string>();
        foreach (var uc in snap.UseCasesWithoutRealizesLink)
            findings.Add($"UseCase {uc.UseCaseId} '{uc.Title}' has no Realizes FR link.");
        foreach (var frId in snap.FunctionalRequirementsWithoutRealizesUseCase)
            findings.Add($"FR {frId} has no Realizes use case link.");
        return findings;
    }
}
